import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.Bqa2y7hU.js";const c=JSON.parse('{"title":"开放 API","description":"在用户中心生成 API Key，用 X-API-Key 请求头调用用户级开放接口。","frontmatter":{"title":"开放 API","description":"在用户中心生成 API Key，用 X-API-Key 请求头调用用户级开放接口。"},"headers":[],"relativePath":"console/openapi.md","filePath":"console/openapi.md","lastUpdated":1789295393000}'),l={name:"console/openapi.md"};function n(h,s,p,d,o,r){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="开放-api-🔌" tabindex="-1">开放 API 🔌 <a class="header-anchor" href="#开放-api-🔌" aria-label="Permalink to &quot;开放 API 🔌&quot;">​</a></h1><p>开放 API 让你用程序调用控制台的能力：查自己的机器人、读日志、发消息、看服务器概况。适合把 Xiaoyi_QQ_V4 接进你自己的面板或运维脚本。</p><p>这页讲怎么拿到 Key、怎么带上它发请求、以及用户级都能调哪些接口。</p><h2 id="_1-生成-api-key" tabindex="-1">1. 生成 API Key <a class="header-anchor" href="#_1-生成-api-key" aria-label="Permalink to &quot;1. 生成 API Key&quot;">​</a></h2><p>进「用户中心」，找到开放 API 区域，生成一个 API Key。</p><table tabindex="0"><thead><tr><th>要点</th><th>说明</th></tr></thead><tbody><tr><td>归属</td><td>Key 属于你的<strong>账号</strong>，不是某台机器人</td></tr><tr><td>权限</td><td>只能访问你自己名下的资源</td></tr><tr><td>保管</td><td>Key 等同于你的身份凭证，不要贴到公开仓库、截图或群里</td></tr></tbody></table><p>如果 Key 泄露了，在同一个页面重新生成一个，旧的随即失效。</p><div class="danger custom-block"><p class="custom-block-title">不要在任何地方公开你的 Key</p><p>本文档里的示例一律用占位值。你自己的 Key 只应出现在服务端配置或环境变量里，不要写进前端代码。</p></div><h2 id="_2-怎么调用" tabindex="-1">2. 怎么调用 <a class="header-anchor" href="#_2-怎么调用" aria-label="Permalink to &quot;2. 怎么调用&quot;">​</a></h2><p>所有请求都通过 <code>X-API-Key</code> 请求头携带凭据。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查询当前账号信息（把占位 Key 换成你自己的）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-API-Key: &lt;你的API Key&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     https://example.com/api/user/info</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出你名下的机器人</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-API-Key: &lt;你的API Key&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">     https://example.com/api/bots</span></span></code></pre></div><p>把 <code>example.com</code> 换成你实际访问控制台用的域名即可。</p><h2 id="_3-用户级可用接口" tabindex="-1">3. 用户级可用接口 <a class="header-anchor" href="#_3-用户级可用接口" aria-label="Permalink to &quot;3. 用户级可用接口&quot;">​</a></h2><p>下面这些接口用<strong>你自己的</strong> API Key 就能调，返回范围限于你名下的资源。</p><table tabindex="0"><thead><tr><th>接口</th><th>用途</th></tr></thead><tbody><tr><td><code>user/info</code></td><td>当前账号信息</td></tr><tr><td><code>user/logs</code></td><td>账号维度的日志</td></tr><tr><td><code>user/notifications</code></td><td>通知中心的消息</td></tr><tr><td><code>user/subscription</code></td><td>当前套餐与额度情况</td></tr><tr><td><code>bots</code></td><td>你的机器人列表</td></tr><tr><td><code>bots/{uuid}</code></td><td>指定机器人的详情</td></tr><tr><td><code>bots/{uuid}/stats</code></td><td>指定机器人的统计数据</td></tr><tr><td><code>bots/{uuid}/send</code></td><td>通过指定机器人发送消息</td></tr><tr><td><code>plans</code></td><td>可购买的套餐列表</td></tr><tr><td><code>plugins</code></td><td>插件市场列表</td></tr><tr><td><code>server/stats</code></td><td>服务器运行概况</td></tr></tbody></table><p><code>{uuid}</code> 就是机器人详情页「设置」Tab 里显示的那个 UUID。</p><div class="tip custom-block"><p class="custom-block-title">先确认机器人 UUID</p><p>调 <code>bots/{uuid}/...</code> 系列接口之前，先在控制台进机器人详情页，从「设置」Tab 复制 UUID，避免手工拼错。</p></div><h2 id="_4-管理级接口" tabindex="-1">4. 管理级接口 <a class="header-anchor" href="#_4-管理级接口" aria-label="Permalink to &quot;4. 管理级接口&quot;">​</a></h2><p>除了用户级接口，还有一组<strong>管理级接口</strong>，用于服务商侧的管理操作。</p><ul><li>管理级接口<strong>不能</strong>用普通用户的 Key 调用</li><li>需要<strong>管理员的 Key</strong>才可用</li><li>具体有哪些管理级接口不在本文档展开</li></ul><p>如果你确实需要管理级能力，请联系服务商。</p><h2 id="_5-调用示例" tabindex="-1">5. 调用示例 <a class="header-anchor" href="#_5-调用示例" aria-label="Permalink to &quot;5. 调用示例&quot;">​</a></h2><p>发消息的接口用 <code>POST</code>，把内容放在请求体里：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 通过指定机器人发一条消息（uuid 与 Key 都换成你自己的）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-API-Key: &lt;你的API Key&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;target&quot;: &quot;&lt;群号或用户ID&gt;&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;message&quot;: &quot;来自开放 API 的问候&quot;   # 消息内容</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">      }&#39;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  https://example.com/api/bots/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">机器人UUI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/send</span></span></code></pre></div><p>不同接口需要的请求体字段不一样，以接口返回的提示为准。调用失败时先看返回里的错误信息，再对照下面的排查表。</p><h2 id="_6-排查" tabindex="-1">6. 排查 <a class="header-anchor" href="#_6-排查" aria-label="Permalink to &quot;6. 排查&quot;">​</a></h2><h3 id="症状-返回-401" tabindex="-1">症状：返回 401 <a class="header-anchor" href="#症状-返回-401" aria-label="Permalink to &quot;症状：返回 401&quot;">​</a></h3><ul><li><strong>原因</strong>：没带 <code>X-API-Key</code>，或者 Key 写错了、已经失效。</li><li><strong>处理方式</strong>：确认请求头名字拼写正确（<code>X-API-Key</code>），到用户中心核对 Key 是否还有效，必要时重新生成。</li></ul><h3 id="症状-返回-403" tabindex="-1">症状：返回 403 <a class="header-anchor" href="#症状-返回-403" aria-label="Permalink to &quot;症状：返回 403&quot;">​</a></h3><ul><li><strong>原因</strong>：用普通用户的 Key 去调管理级接口，或者访问了不属于你的资源。</li><li><strong>处理方式</strong>：确认接口是否属于用户级；跨账号访问一律不允许。</li></ul><h3 id="症状-返回-404" tabindex="-1">症状：返回 404 <a class="header-anchor" href="#症状-返回-404" aria-label="Permalink to &quot;症状：返回 404&quot;">​</a></h3><ul><li><strong>原因</strong>：路径拼错，或 <code>{uuid}</code> 不是你的机器人。</li><li><strong>处理方式</strong>：从机器人详情页复制 UUID 重试。</li></ul><h3 id="症状-机器人不回复-但接口返回成功" tabindex="-1">症状：机器人不回复，但接口返回成功 <a class="header-anchor" href="#症状-机器人不回复-但接口返回成功" aria-label="Permalink to &quot;症状：机器人不回复，但接口返回成功&quot;">​</a></h3><ul><li><strong>原因</strong>：机器人本身离线，或目标 ID 不对。</li><li><strong>处理方式</strong>：先到控制台确认机器人状态在线，并核对目标群号 / 用户 ID。</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux / macOS：把响应头和状态码一起打出来，方便定位</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-API-Key: &lt;你的API Key&gt;&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/api/bots</span></span></code></pre></div><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows PowerShell：等价的写法</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Invoke-RestMethod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Uri </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/api/bots&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> \`</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Headers </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;X-API-Key&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;&lt;你的API Key&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/RuaBot.Doc/console/overview">控制台总览</a></li><li><a href="/RuaBot.Doc/console/bots">我的机器人</a></li><li><a href="/RuaBot.Doc/console/billing">订阅 · 卡密 · 充值</a></li></ul>`,39)])])}const g=a(l,[["render",n]]);export{c as __pageData,g as default};
